def isValid(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch not in pairs:      # 左括号入栈
            stack.append(ch)
        elif not stack or stack.pop() != pairs[ch]:
            return False         # 右括号配不上
    return not stack             # 栈空才有效

class MinStack:
    def __init__(self):
        self.st, self.mn = [], []
    def push(self, val):
        self.st.append(val)      # 主栈入数据
        self.mn.append(min(val, self.mn[-1] if self.mn else val))
    def pop(self):
        self.st.pop(); self.mn.pop()  # 两栈同步
    def top(self):
        return self.st[-1]
    def getMin(self):
        return self.mn[-1]       # 栈顶即当前最小

def dailyTemperatures(t):
    ans = [0] * len(t)
    stack = []                # 下标栈，温度单调递减
    for i, x in enumerate(t):
        while stack and t[stack[-1]] < x:
            j = stack.pop()
            ans[j] = i - j    # 回填等待天数
        stack.append(i)
    return ans

def largestRectangleArea(hs):
    hs = [0] + hs + [0]       # 首尾哨兵
    stack, best = [], 0
    for i, h in enumerate(hs):
        while stack and hs[stack[-1]] > h:
            height = hs[stack.pop()]   # 弹出柱为高
            best = max(best, height * (i - stack[-1] - 1))
        stack.append(i)
    return best

def decodeString(s):
    res, num, st_p, st_n = '', 0, [], []
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)    # 累积倍数
        elif ch == '[':
            st_p.append(res); st_n.append(num)
            res, num = '', 0            # 清空进内层
        elif ch == ']':
            res = st_p.pop() + res * st_n.pop()  # 展开拼接
        else:
            res += ch
    return res
